// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IFundingRateCondition {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Enums              ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    enum Comparison {
        LESS,
        GREATER,
        EQUAL,
        GREATER_OR_EQUAL,
        LESS_OR_EQUAL,
        NOT_EQUAL
    }

    enum PositionType {
        LONG,
        SHORT
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Structs            ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    struct Condition {
        Comparison comparison;
        PositionType positionType;
        address baseToken;
        int256 fundingRate;
        bool withDeltaPercentage;
        uint256 deltaPercentage;
        bool updateable;
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃        Events             ┃
